"use strict";
import { useCallback, useMemo, useState, useEffect } from "react";
import { useAccount, useWriteContract, useWaitForTransactionReceipt, useReadContract } from "wagmi";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { formatEther } from "viem";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
export function useVoterContract() {
  const { address: account } = useAccount();
  const { writeContract, data: hash, isPending, error: writeError } = useWriteContract();
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({
    hash
  });
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const transactionState = useMemo(() => ({
    isLoading: isPending,
    isConfirming,
    isSuccess,
    error: writeError?.message || null,
    hash
  }), [isPending, isConfirming, isSuccess, writeError, hash]);
  const [pendingVoteAction, setPendingVoteAction] = useState(null);
  useEffect(() => {
    if (isSuccess && hash && pendingVoteAction) {
      let title = "";
      let description = "";
      switch (pendingVoteAction.action) {
        case "vote":
          title = "Vote Submitted";
          description = `Successfully voted on ${pendingVoteAction.poolCount} pool${pendingVoteAction.poolCount > 1 ? "s" : ""} with veABX #${pendingVoteAction.tokenId}`;
          break;
        case "reset":
          title = "Votes Reset";
          description = `Successfully reset votes for veABX #${pendingVoteAction.tokenId}`;
          break;
        case "poke":
          title = "Voting Power Updated";
          description = `Successfully updated voting power for veABX #${pendingVoteAction.tokenId}`;
          break;
        case "claimFees":
          title = "Fees Claimed";
          description = `Successfully claimed fees for veABX #${pendingVoteAction.tokenId}`;
          break;
        case "claimBribes":
          title = "Bribes Claimed";
          description = `Successfully claimed bribes for veABX #${pendingVoteAction.tokenId}`;
          break;
        case "claimGaugeRewards":
          title = "Gauge Rewards Claimed";
          description = `Successfully claimed rewards from ${pendingVoteAction.gaugeCount} gauge${pendingVoteAction.gaugeCount > 1 ? "s" : ""}`;
          break;
      }
      popupRegistry.addPopup({
        type: PopupType.VotingSuccess,
        content: {
          type: "success",
          title,
          description,
          hash,
          action: pendingVoteAction.action
        }
      }, `voting-success-${hash}`);
      setPendingVoteAction(null);
    }
  }, [isSuccess, hash, pendingVoteAction]);
  const vote = useCallback(async (tokenId, votes) => {
    if (!voterAddress || !voterAbi) {
      console.error("Missing contract details:", { voterAddress, voterAbi: !!voterAbi });
      throw new Error("Voter contract not available");
    }
    if (votes.length === 0) {
      throw new Error("No votes provided");
    }
    if (votes.length > 30) {
      throw new Error("Maximum 30 pools per vote");
    }
    const poolAddresses = votes.map((v) => v.poolAddress);
    const weights = votes.map((v) => BigInt(v.weight));
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "vote",
        args: [BigInt(tokenId), poolAddresses, weights]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      const poolCount = votes.length;
      setPendingVoteAction({
        action: "vote",
        tokenId,
        poolCount
      });
    } catch (error) {
      console.error("Vote transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Vote Failed",
          description: `Failed to submit vote: ${error.message}`,
          action: "vote"
        }
      }, `voting-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  const resetVotes = useCallback(async (tokenId) => {
    if (!voterAddress || !voterAbi) {
      throw new Error("Voter contract not available");
    }
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "reset",
        args: [BigInt(tokenId)]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      setPendingVoteAction({
        action: "reset",
        tokenId
      });
    } catch (error) {
      console.error("Reset votes transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Reset Failed",
          description: `Failed to reset votes: ${error.message}`,
          action: "reset"
        }
      }, `voting-reset-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  const pokeVotes = useCallback(async (tokenId) => {
    if (!voterAddress || !voterAbi) {
      throw new Error("Voter contract not available");
    }
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "poke",
        args: [BigInt(tokenId)]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      setPendingVoteAction({
        action: "poke",
        tokenId
      });
    } catch (error) {
      console.error("Poke votes transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Update Voting Power Failed",
          description: `Failed to update voting power: ${error.message}`,
          action: "poke"
        }
      }, `voting-poke-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  const claimFees = useCallback(async (tokenId, feeContracts, tokens) => {
    if (!voterAddress || !voterAbi) {
      throw new Error("Voter contract not available");
    }
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "claimFees",
        args: [
          feeContracts,
          tokens,
          BigInt(tokenId)
        ]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      setPendingVoteAction({
        action: "claimFees",
        tokenId
      });
    } catch (error) {
      console.error("Claim fees transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Claim Fees Failed",
          description: `Failed to claim fees: ${error.message}`,
          action: "claimFees"
        }
      }, `voting-fees-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  const claimBribes = useCallback(async (tokenId, bribeContracts, tokens) => {
    if (!voterAddress || !voterAbi) {
      throw new Error("Voter contract not available");
    }
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "claimBribes",
        args: [
          bribeContracts,
          tokens,
          BigInt(tokenId)
        ]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      setPendingVoteAction({
        action: "claimBribes",
        tokenId
      });
    } catch (error) {
      console.error("Claim bribes transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Claim Bribes Failed",
          description: `Failed to claim bribes: ${error.message}`,
          action: "claimBribes"
        }
      }, `voting-bribes-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  const claimGaugeRewards = useCallback(async (gaugeAddresses) => {
    if (!voterAddress || !voterAbi) {
      throw new Error("Voter contract not available");
    }
    try {
      const result = await writeContract({
        address: voterAddress,
        abi: voterAbi,
        functionName: "claimRewards",
        args: [gaugeAddresses]
      });
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
      const gaugeCount = gaugeAddresses.length;
      setPendingVoteAction({
        action: "claimGaugeRewards",
        tokenId: "",
        // Not applicable for gauge rewards
        gaugeCount
      });
    } catch (error) {
      console.error("Claim gauge rewards transaction failed:", error);
      popupRegistry.addPopup({
        type: PopupType.VotingError,
        content: {
          type: "error",
          title: "Claim Gauge Rewards Failed",
          description: `Failed to claim gauge rewards: ${error.message}`,
          action: "claimGaugeRewards"
        }
      }, `voting-gauge-rewards-error-${Date.now()}`);
      throw error;
    }
  }, [voterAddress, voterAbi, writeContract]);
  return {
    // Contract details
    voterAddress,
    // Voting functions
    vote,
    resetVotes,
    pokeVotes,
    // Reward claiming functions
    claimFees,
    claimBribes,
    claimGaugeRewards,
    // Transaction state
    transactionState
  };
}
export function useVoterReads() {
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const [currentTimestamp, setCurrentTimestamp] = useState(() => BigInt(Math.floor(Date.now() / 1e3)));
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTimestamp(BigInt(Math.floor(Date.now() / 1e3)));
    }, 5 * 60 * 1e3);
    return () => clearInterval(interval);
  }, []);
  const { data: epochStart } = useReadContract({
    address: voterAddress,
    abi: voterAbi,
    functionName: "epochStart",
    args: [currentTimestamp]
  });
  const { data: epochNext } = useReadContract({
    address: voterAddress,
    abi: voterAbi,
    functionName: "epochNext",
    args: [currentTimestamp]
  });
  const { data: epochVoteStart } = useReadContract({
    address: voterAddress,
    abi: voterAbi,
    functionName: "epochVoteStart",
    args: [currentTimestamp]
  });
  const { data: epochVoteEnd } = useReadContract({
    address: voterAddress,
    abi: voterAbi,
    functionName: "epochVoteEnd",
    args: [currentTimestamp]
  });
  const useUserVotesForToken = useCallback((tokenId) => {
    return useReadContract({
      address: voterAddress,
      abi: voterAbi,
      functionName: "votes",
      args: tokenId ? [BigInt(tokenId)] : void 0,
      query: { enabled: !!tokenId }
    });
  }, [voterAddress, voterAbi]);
  return {
    // Epoch timing
    epochStart: epochStart ? Number(epochStart) : void 0,
    epochNext: epochNext ? Number(epochNext) : void 0,
    epochVoteStart: epochVoteStart ? Number(epochVoteStart) : void 0,
    epochVoteEnd: epochVoteEnd ? Number(epochVoteEnd) : void 0,
    // Helper functions
    useUserVotesForToken
  };
}
export const VotingUtils = {
  /**
   * Calculate actual vote weights based on proportional weights and total voting power
   */
  calculateActualWeights: (votes, totalVotingPower) => {
    const totalProportional = votes.reduce((sum, vote) => sum + vote.weight, 0);
    if (totalProportional === 0) return votes.map((v) => ({ ...v, actualWeight: 0 }));
    return votes.map((vote) => ({
      ...vote,
      actualWeight: vote.weight * totalVotingPower / totalProportional,
      percentage: vote.weight / totalProportional * 100
    }));
  },
  /**
   * Validate voting constraints
   */
  validateVotes: (votes) => {
    if (votes.length === 0) {
      throw new Error("No votes provided");
    }
    if (votes.length > 30) {
      throw new Error("Maximum 30 pools per vote");
    }
    const totalWeight = votes.reduce((sum, vote) => sum + vote.weight, 0);
    if (totalWeight === 0) {
      throw new Error("Total vote weight cannot be zero");
    }
    const poolAddresses = votes.map((v) => v.poolAddress.toLowerCase());
    const uniquePools = new Set(poolAddresses);
    if (uniquePools.size !== poolAddresses.length) {
      throw new Error("Cannot vote for the same pool multiple times");
    }
    return true;
  },
  /**
   * Check if we're in the distribution window (first 6 hours of epoch)
   */
  isDistributionWindow: (epochStart, currentTime = Date.now() / 1e3) => {
    const DISTRIBUTION_WINDOW = 6 * 60 * 60;
    return currentTime >= epochStart && currentTime < epochStart + DISTRIBUTION_WINDOW;
  },
  /**
   * Format voting power for display
   */
  formatVotingPower: (votingPower) => {
    const power = typeof votingPower === "string" ? BigInt(votingPower) : votingPower;
    return formatEther(power);
  }
};
